import java.util.ArrayList;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

interface Graph<T> {
    Iterable<T> vertices();
    Iterable<T> getNeighbors(T v);
}

class AdjacencyListGraph<T> implements Graph<T> {
    private Map<T, ArrayList<T>> adj;

    AdjacencyListGraph() {
        adj = new LinkedHashMap<>();
    }

    void addEdge(T u, T v) {
        adj.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        adj.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    @Override
    public Iterable<T> vertices() {
        return adj.keySet();
    }

    @Override
    public Iterable<T> getNeighbors(T v) {
        return adj.getOrDefault(v, new ArrayList<>());
    }
}

class GraphTraversal {

    static class BFSContext<T> {
        private Set<T> visited;
        private ArrayList<T> component;

        BFSContext() {
            visited = new HashSet<>();
            component = new ArrayList<>();
        }

        boolean isVisited(T v) {
            return visited.contains(v);
        }

        void markVisited(T v) {
            visited.add(v);
        }

        void addToComponent(T v) {
            component.add(v);
        }

        void resetComponent() {
            component = new ArrayList<>();
        }

        ArrayList<T> getComponent() {
            return component;
        }
    }

    static <T> void bfs(Graph<T> g, T src, BFSContext<T> ctx) {
        Queue<T> q = new LinkedList<>();
        ctx.markVisited(src);
        q.add(src);

        while (!q.isEmpty()) {
            T curr = q.poll();
            ctx.addToComponent(curr);

            for (T x : g.getNeighbors(curr)) {
                if (!ctx.isVisited(x)) {
                    ctx.markVisited(x);
                    q.add(x);
                }
            }
        }
    }
}

class ConnectedComponents {

    static class ComponentIterator<T> implements Iterator<ArrayList<T>> {
        private final Graph<T> g;
        private final Iterator<T> vertexIter;
        private final GraphTraversal.BFSContext<T> ctx;
        private T nextUnvisited;

        ComponentIterator(Graph<T> g) {
            this.g = g;
            this.ctx = new GraphTraversal.BFSContext<>();
            this.vertexIter = g.vertices().iterator();
            advance();
        }

        private void advance() {
            nextUnvisited = null;
            while (vertexIter.hasNext()) {
                T v = vertexIter.next();
                if (!ctx.isVisited(v)) {
                    nextUnvisited = v;
                    break;
                }
            }
        }

        @Override
        public boolean hasNext() {
            return nextUnvisited != null;
        }

        @Override
        public ArrayList<T> next() {
            ctx.resetComponent();
            GraphTraversal.bfs(g, nextUnvisited, ctx);
            advance();
            return ctx.getComponent();
        }
    }

    static <T> ArrayList<ArrayList<T>> getComponents(Graph<T> g) {
        ArrayList<ArrayList<T>> res = new ArrayList<>();
        ComponentIterator<T> it = new ComponentIterator<>(g);
        while (it.hasNext()) {
            res.add(it.next());
        }
        return res;
    }

    public static void main(String[] args) {
        AdjacencyListGraph<Integer> g = new AdjacencyListGraph<>();

        g.addEdge(1, 2);
        g.addEdge(0, 3);
        g.addEdge(2, 0);
        g.addEdge(5, 4);

        ArrayList<ArrayList<Integer>> res = getComponents(g);

        for (ArrayList<Integer> component : res) {
            for (int vertex : component) {
                System.out.print(vertex + " ");
            }
            System.out.println();
        }
    }
}

